-- D40: selective transactional full quote templates; no existing record backfill.
ALTER TABLE public.quote_templates ADD COLUMN IF NOT EXISTS full_quote_snapshot jsonb;
COMMENT ON COLUMN public.quote_templates.full_quote_snapshot IS 'Versioned relative full-quote snapshot; NULL denotes reduced legacy template requiring re-save for full fee fidelity.';
CREATE TABLE public.quote_template_imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL REFERENCES public.fee_proposals(id) ON DELETE CASCADE,actor_id uuid NOT NULL,template_id uuid REFERENCES public.quote_templates(id) ON DELETE SET NULL,before_state jsonb NOT NULL,after_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),undone_at timestamptz);
GRANT SELECT ON public.quote_template_imports TO authenticated;
GRANT ALL ON public.quote_template_imports TO service_role;
REVOKE ALL ON public.quote_template_imports FROM anon;
REVOKE TRUNCATE ON public.quote_template_imports FROM anon,authenticated;
ALTER TABLE public.quote_template_imports ENABLE ROW LEVEL SECURITY;
CREATE POLICY quote_import_history_read ON public.quote_template_imports FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'::public.app_role));
CREATE OR REPLACE FUNCTION public.quote_template_rewrite(_value jsonb,_ids jsonb,_sanitize boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$
DECLARE result jsonb;k text;v jsonb;s text;old text;replacement text;
BEGIN
 IF jsonb_typeof(_value)='object' THEN result:='{}'; FOR k,v IN SELECT * FROM jsonb_each(_value) LOOP
 IF _sanitize AND k=ANY(ARRAY['client_snapshot','project_snapshot','client_id','client_name','company_id','contact_id','contact_name','contact_salutation','project_name','project_id','proposal_number','address','addresses','location','cover_title','cover_subtitle','cover_reference','external_id','image_id','attachment_path']) THEN CONTINUE; END IF;
 result:=result||jsonb_build_object(k,public.quote_template_rewrite(v,_ids,_sanitize)); END LOOP; RETURN result;
 ELSIF jsonb_typeof(_value)='array' THEN SELECT coalesce(jsonb_agg(public.quote_template_rewrite(value,_ids,_sanitize) ORDER BY ord),'[]') INTO result FROM jsonb_array_elements(_value) WITH ORDINALITY t(value,ord);RETURN result;
 ELSIF jsonb_typeof(_value)='string' THEN s:=_value#>>'{}';FOR old,replacement IN SELECT key,value FROM jsonb_each_text(_ids) ORDER BY length(key) DESC LOOP IF old<>'' THEN s:=replace(s,old,replacement);END IF;END LOOP;RETURN to_jsonb(s);END IF;RETURN _value;
END $$;
CREATE OR REPLACE FUNCTION public.quote_template_capture(_quote uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE q jsonb;tables jsonb:='{}';t text;rows jsonb;p jsonb;blocks jsonb;
BEGIN
 SELECT to_jsonb(f) INTO q FROM public.fee_proposals f WHERE id=_quote;
 FOREACH t IN ARRAY ARRAY['quote_stages','quote_stage_dependencies','quote_allocations','quote_external_services','quote_stage_supplier_costs','quote_supplier_markups','quote_supplier_phase_splits','quote_site_trips','quote_billable_hourly_rates','quote_payment_schedule_items'] LOOP
 EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),''[]''::jsonb) FROM public.%I r WHERE quote_id=$1',t) INTO rows USING _quote;tables:=tables||jsonb_build_object(t,rows);END LOOP;
 SELECT to_jsonb(r) INTO p FROM public.psa_proposals r WHERE quote_id=_quote ORDER BY updated_at DESC,id LIMIT 1;
 SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]') INTO blocks FROM public.psa_proposal_blocks r WHERE proposal_id=(p->>'id')::uuid;
 RETURN jsonb_build_object('quote',q,'tables',tables,'proposal',p,'blocks',blocks);
END $$;
REVOKE ALL ON FUNCTION public.quote_template_capture(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.quote_template_snapshot(_quote uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE raw jsonb;settings jsonb;tables jsonb:='{}';t text;rows jsonb;r jsonb;anchor date;d text;date_value date;identity jsonb:='{}';q jsonb;p jsonb;s numeric;c record;
BEGIN
 raw:=public.quote_template_capture(_quote);q:=raw->'quote';p:=raw->'proposal';SELECT min(start_date) INTO anchor FROM public.quote_stages WHERE quote_id=_quote;anchor:=coalesce(anchor,date '2000-01-03');
 SELECT coalesce(jsonb_object_agg(key,value),'{}') INTO settings FROM jsonb_each(q) WHERE key=ANY(ARRAY['valor','fee_structure_type','construction_cost','fee_percentage','pricing_multiplier','time_based_settings','quote_category','project_fee_calculation','fee_source_mode','quote_build_settings','trip_billing_mode','sale_margin_pct','default_vat_rate','default_payment_terms','first_payment_terms','invoice_grouping_enabled','invoice_grouping_days']);
 IF length(coalesce(q->>'titulo',''))>2 THEN identity:=identity||jsonb_build_object(q->>'titulo','{{project_name}}');END IF;
 IF length(coalesce(q->>'proposal_number',''))>2 THEN identity:=identity||jsonb_build_object(q->>'proposal_number','{{project_number}}');END IF;
 FOR c IN SELECT nome FROM public.companies WHERE id=(q->>'company_id')::uuid LOOP IF length(coalesce(c.nome,''))>2 THEN identity:=identity||jsonb_build_object(c.nome,'{{client_name}}');END IF;END LOOP;
 FOREACH t IN ARRAY ARRAY['quote_stages','quote_stage_dependencies','quote_allocations','quote_external_services','quote_stage_supplier_costs','quote_supplier_markups','quote_supplier_phase_splits','quote_site_trips','quote_billable_hourly_rates','quote_payment_schedule_items'] LOOP
 rows:='[]';FOR r IN SELECT value FROM jsonb_array_elements(raw->'tables'->t) LOOP
 r:=r-'created_at'-'updated_at'-'external_id'-'notes'-'archived_at';IF t='quote_external_services' THEN r:=r-'status';END IF;
 IF t='quote_payment_schedule_items' THEN SELECT coalesce(jsonb_object_agg(key,value),'{}') INTO r FROM jsonb_each(r) WHERE key=ANY(ARRAY['id','quote_id','stage_id','sort_order','trigger_type','amount_type','amount_value','payment_offset_days','vat_rate','vat_rate_override','payment_terms','direction','supplier_company_id','supplier_id']);
 IF r->>'amount_type'='fixed' THEN SELECT coalesce(budget,0) INTO s FROM public.quote_stages WHERE id=(r->>'stage_id')::uuid;r:=r||jsonb_build_object('amount_type','percent','amount_value',CASE WHEN coalesce(s,0)>0 THEN (r->>'amount_value')::numeric/s*100 ELSE 0 END);END IF;r:=r||jsonb_build_object('label',r->>'trigger_type');END IF;
 FOREACH d IN ARRAY ARRAY['start_date','end_date','custom_date','retainer_anchor_month'] LOOP IF r ? d AND r->>d IS NOT NULL THEN date_value:=(r->>d)::date;date_value:=public.pm_relative_from_calendar(anchor,date_value,d<>'end_date');r:=r||jsonb_build_object(d,to_char(date_value,'YYYY-MM-DD'));END IF;END LOOP;
 IF t='quote_stages' THEN r:=r||jsonb_build_object('date_mode','relative');END IF;rows:=rows||jsonb_build_array(r);END LOOP;tables:=tables||jsonb_build_object(t,rows);END LOOP;
 RETURN jsonb_build_object('version',2,'settings',settings,'tables',tables,'blocks',public.quote_template_rewrite(raw->'blocks',identity,true),'layout',coalesce(p->'style_settings','{}'),'language',coalesce(p->>'language','pt-PT'));
END $$;
REVOKE ALL ON FUNCTION public.quote_template_snapshot(uuid) FROM PUBLIC,anon,authenticated;
-- New saves include a full snapshot; reduced child projections remain for legacy consumers.
CREATE OR REPLACE FUNCTION public.quote_save_as_template(_quote_id uuid,_name text,_description text,_category public.crm_quote_category,_project_type text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE tid uuid;snapshot jsonb;r jsonb;maps jsonb:='{}';key_name text;
BEGIN
 IF NOT public.has_role(auth.uid(),'admin'::public.app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.fee_proposals WHERE id=_quote_id) THEN RAISE EXCEPTION 'quote not found';END IF;
 IF length(trim(coalesce(_name,'')))=0 THEN RAISE EXCEPTION 'name is required';END IF;
 snapshot:=public.quote_template_snapshot(_quote_id);
 INSERT INTO public.quote_templates(name,description,category,project_type,created_by,full_quote_snapshot) VALUES(trim(_name),_description,coalesce(_category,'project'),coalesce(nullif(trim(_project_type),''),'generic'),auth.uid(),snapshot) RETURNING id INTO tid;
 FOR r IN SELECT value FROM jsonb_array_elements(snapshot->'tables'->'quote_stages') LOOP key_name:='s'||r->>'sort_order'||'_'||substring(r->>'id',1,8);maps:=maps||jsonb_build_object(r->>'id',key_name);
 INSERT INTO public.quote_template_stages(template_id,stage_temp_key,sort_order,title,duration_days,fee_percentage,fee_amount,color,billing_trigger_default) VALUES(tid,key_name,(r->>'sort_order')::integer,r->>'name',greatest(1,(r->>'end_date')::date-(r->>'start_date')::date+1),0,coalesce((r->>'budget')::numeric,0),r->>'color','stage_end');END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(snapshot->'tables'->'quote_stage_dependencies') LOOP INSERT INTO public.quote_template_dependencies(template_id,predecessor_stage_temp_key,successor_stage_temp_key,dependency_type,lag_days) VALUES(tid,maps->>(r->>'predecessor_stage_id'),maps->>(r->>'successor_stage_id'),(r->>'type')::public.quote_dep_type,(r->>'lag_days')::integer);END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(snapshot->'tables'->'quote_payment_schedule_items') LOOP INSERT INTO public.quote_template_payment_rules(template_id,stage_temp_key,sort_order,label,trigger_type,amount_type,amount_value,payment_terms_days) VALUES(tid,maps->>(r->>'stage_id'),(r->>'sort_order')::integer,r->>'label',(r->>'trigger_type')::public.quote_payment_trigger,(r->>'amount_type')::public.quote_payment_amount_type,(r->>'amount_value')::numeric,coalesce((r->>'payment_offset_days')::integer,30));END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(snapshot->'tables'->'quote_external_services') LOOP INSERT INTO public.quote_template_external_services(template_id,stage_temp_key,description,quantity,unit_cost,markup_type,markup_value) VALUES(tid,maps->>(r->>'stage_id'),r->>'description',(r->>'quantity')::numeric,(r->>'unit_cost')::numeric,(r->>'markup_type')::public.quote_markup_type,(r->>'markup_value')::numeric);END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(snapshot->'blocks') LOOP INSERT INTO public.quote_template_blocks(template_id,block_title,sort_order,required,block_type,source_type,source_ref,content_rich,contract_relevance) VALUES(tid,r->>'title',(r->>'sort_order')::integer,false,(r->>'block_type')::public.psa_block_type,(r->>'source_type')::public.psa_block_source_type,r->'source_ref',r->'content_rich',(r->>'contract_relevance')::public.psa_contract_relevance);END LOOP;
 RETURN tid;
END $$;
CREATE OR REPLACE FUNCTION public.quote_template_legacy(_template uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE stages jsonb:='[]';maps jsonb:='{}';blocks jsonb;deps jsonb;payments jsonb;services jsonb;r record;next_date date:=date '2000-01-03';sid uuid;b jsonb;oldid text;
BEGIN
 FOR r IN SELECT * FROM public.quote_template_stages WHERE template_id=_template ORDER BY sort_order,stage_temp_key LOOP sid:=gen_random_uuid();maps:=maps||jsonb_build_object(r.stage_temp_key,sid);stages:=stages||jsonb_build_array(jsonb_build_object('id',sid,'name',r.title,'start_date',next_date,'end_date',next_date+r.duration_days-1,'sort_order',r.sort_order,'color',r.color,'budget',r.fee_amount,'date_mode','relative'));next_date:=next_date+r.duration_days;END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'predecessor_stage_id',maps->>predecessor_stage_temp_key,'successor_stage_id',maps->>successor_stage_temp_key,'type',dependency_type,'lag_days',lag_days)),'[]') INTO deps FROM public.quote_template_dependencies WHERE template_id=_template;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'stage_id',maps->>stage_temp_key,'sort_order',sort_order,'trigger_type',trigger_type,'amount_type',amount_type,'amount_value',amount_value,'label',trigger_type,'payment_offset_days',payment_terms_days)),'[]') INTO payments FROM public.quote_template_payment_rules WHERE template_id=_template;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'stage_id',maps->>stage_temp_key,'description',description,'quantity',quantity,'unit_cost',unit_cost,'purchase_price',unit_cost*quantity,'markup_type',markup_type,'markup_value',markup_value)),'[]') INTO services FROM public.quote_template_external_services WHERE template_id=_template;
 blocks:='[]';FOR r IN SELECT tb.*,pb.default_content FROM public.quote_template_blocks tb LEFT JOIN public.proposal_blocks pb ON pb.id=tb.proposal_block_id WHERE tb.template_id=_template ORDER BY tb.sort_order LOOP
 b:=jsonb_build_object('id',r.id,'sort_order',r.sort_order,'block_type',coalesce(r.block_type,'custom_text'),'title',r.block_title,'source_type',coalesce(r.source_type,'library'),'source_ref',coalesce(r.source_ref,'{}'),'content_rich',coalesce(r.content_rich,jsonb_build_object('html',coalesce(r.default_content,''))),'contract_relevance',coalesce(r.contract_relevance,'proposal_only'));
 FOR oldid IN SELECT value#>>'{}' FROM jsonb_each(coalesce(r.source_ref,'{}')) WHERE key IN('stage_id','parent_stage_id') AND jsonb_typeof(value)='string' LOOP SELECT maps->>stage_temp_key INTO sid FROM public.quote_template_stages WHERE template_id=_template AND right(stage_temp_key,8)=substring(oldid,1,8);IF sid IS NULL THEN RAISE EXCEPTION 'Legacy template stage reference cannot be recovered; re-save this template';END IF;maps:=maps||jsonb_build_object(oldid,sid);END LOOP;blocks:=blocks||jsonb_build_array(b);END LOOP;
 RETURN jsonb_build_object('version',1,'settings','{}'::jsonb,'tables',jsonb_build_object('quote_stages',stages,'quote_stage_dependencies',deps,'quote_payment_schedule_items',payments,'quote_external_services',services),'blocks',public.quote_template_rewrite(blocks,maps,true),'layout','{}'::jsonb,'language','pt-PT');
END $$;
REVOKE ALL ON FUNCTION public.quote_template_legacy(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.quote_template_insert_rows(_table text,_rows jsonb,_ids jsonb,_quote uuid,_keep_ids boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r jsonb;cols text;vals text;key_name text;field_value jsonb;
BEGIN
 IF NOT(_table=ANY(ARRAY['quote_stages','quote_stage_dependencies','quote_allocations','quote_external_services','quote_stage_supplier_costs','quote_supplier_markups','quote_supplier_phase_splits','quote_site_trips','quote_billable_hourly_rates','quote_payment_schedule_items','psa_proposal_blocks'])) THEN RAISE EXCEPTION 'Invalid snapshot table';END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(coalesce(_rows,'[]')) LOOP IF NOT _keep_ids THEN r:=public.quote_template_rewrite(r,_ids,false);END IF;IF _table<>'psa_proposal_blocks' THEN r:=r||jsonb_build_object('quote_id',_quote);END IF;cols:=NULL;vals:=NULL;
 FOR key_name,field_value IN SELECT e.key,e.value FROM jsonb_each(r) e JOIN information_schema.columns c ON c.table_schema='public' AND c.table_name=_table AND c.column_name=e.key WHERE c.is_generated='NEVER' LOOP cols:=concat_ws(',',cols,quote_ident(key_name));vals:=concat_ws(',',vals,format('(jsonb_populate_record(NULL::public.%I,$1)).%I',_table,key_name));END LOOP;
 EXECUTE format('INSERT INTO public.%I (%s) SELECT %s',_table,cols,vals) USING r;END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.quote_template_insert_rows(text,jsonb,jsonb,uuid,boolean) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.quote_template_preview(_quote_id uuid,_template_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE b jsonb;s jsonb;counts jsonb;existing jsonb;
BEGIN
 IF NOT public.has_role(auth.uid(),'admin'::public.app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;
 b:=public.quote_template_capture(_quote_id);SELECT full_quote_snapshot INTO s FROM public.quote_templates WHERE id=_template_id AND is_active;IF NOT FOUND THEN RAISE EXCEPTION 'template not found';END IF;IF s IS NULL THEN s:=public.quote_template_legacy(_template_id);END IF;
 counts:=jsonb_build_object('planning',jsonb_array_length(s->'tables'->'quote_stages'),'blocks',jsonb_array_length(s->'blocks'),'payments',jsonb_array_length(coalesce(s->'tables'->'quote_payment_schedule_items','[]')),'fees',jsonb_array_length(coalesce(s->'tables'->'quote_external_services','[]'))+jsonb_array_length(coalesce(s->'tables'->'quote_allocations','[]'))+jsonb_array_length(coalesce(s->'tables'->'quote_site_trips','[]'))+jsonb_array_length(coalesce(s->'tables'->'quote_billable_hourly_rates','[]')),'layout',CASE WHEN s->'layout'<>'{}'::jsonb THEN 1 ELSE 0 END);
 existing:=jsonb_build_object('planning',jsonb_array_length(b->'tables'->'quote_stages'),'blocks',jsonb_array_length(b->'blocks'),'payments',jsonb_array_length(b->'tables'->'quote_payment_schedule_items'),'fees',CASE WHEN jsonb_array_length(b->'tables'->'quote_allocations')+jsonb_array_length(b->'tables'->'quote_external_services')+jsonb_array_length(b->'tables'->'quote_site_trips')+jsonb_array_length(b->'tables'->'quote_billable_hourly_rates')>0 OR (b->'quote'->>'valor')::numeric<>0 OR b->'quote'->'project_fee_calculation'<>'{}'::jsonb THEN 1 ELSE 0 END,'layout',CASE WHEN coalesce(b->'proposal'->'style_settings','{}')<>'{}'::jsonb THEN 1 ELSE 0 END);
 RETURN jsonb_build_object('version',s->'version','counts',counts,'existing',existing,'revision',md5(b::text));
END $$;
CREATE OR REPLACE FUNCTION public.quote_import_full_template(_quote_id uuid,_template_id uuid,_sections jsonb,_revision text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE q public.fee_proposals;b jsonb;s jsonb;maps jsonb:='{}';selected text[]:=ARRAY[]::text[];t text;r jsonb;stages jsonb;settings jsonb;k text;cols text;p uuid;import_id uuid;planning boolean:=coalesce((_sections->>'planning')::boolean,false);fees boolean:=coalesce((_sections->>'fees')::boolean,false);payments boolean:=coalesce((_sections->>'payments')::boolean,false);blocks boolean:=coalesce((_sections->>'blocks')::boolean,false);layout boolean:=coalesce((_sections->>'layout')::boolean,false);fee_values boolean:=coalesce((_sections->>'feeValues')::boolean,true);destination uuid;
BEGIN
 IF NOT public.has_role(auth.uid(),'admin'::public.app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO q FROM public.fee_proposals WHERE id=_quote_id FOR UPDATE;IF NOT FOUND OR q.is_locked OR q.pm_project_id IS NOT NULL OR q.locked_project_id IS NOT NULL OR q.quote_status<>'draft' THEN RAISE EXCEPTION 'Import requires an editable unconverted draft';END IF;
 b:=public.quote_template_capture(_quote_id);IF md5(b::text) IS DISTINCT FROM _revision THEN RAISE EXCEPTION 'Quote changed; review replacement again';END IF;
 SELECT full_quote_snapshot INTO s FROM public.quote_templates WHERE id=_template_id AND is_active;IF NOT FOUND THEN RAISE EXCEPTION 'template not found';END IF;IF s IS NULL THEN s:=public.quote_template_legacy(_template_id);END IF;
 IF NOT(planning OR fees OR payments OR blocks OR layout) THEN RAISE EXCEPTION 'Select at least one section';END IF;
 IF planning AND ((NOT fees AND jsonb_array_length(b->'tables'->'quote_allocations')+jsonb_array_length(b->'tables'->'quote_external_services')+jsonb_array_length(b->'tables'->'quote_site_trips')+jsonb_array_length(b->'tables'->'quote_stage_supplier_costs')+jsonb_array_length(b->'tables'->'quote_supplier_phase_splits')>0) OR (NOT payments AND jsonb_array_length(b->'tables'->'quote_payment_schedule_items')>0) OR (NOT blocks AND jsonb_array_length(b->'blocks')>0)) THEN RAISE EXCEPTION 'Stage replacement requires selecting populated linked fee, payment and block sections';END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(s->'tables'->'quote_stages') LOOP IF planning THEN destination:=gen_random_uuid();ELSE SELECT id INTO destination FROM public.quote_stages WHERE quote_id=_quote_id AND sort_order=(r->>'sort_order')::integer AND name=r->>'name';IF destination IS NULL AND(fees OR payments OR blocks) THEN RAISE EXCEPTION 'Import Planning too: template stage has no destination mapping';END IF;END IF;maps:=maps||jsonb_build_object(r->>'id',destination);END LOOP;
 IF fees THEN selected:=selected||ARRAY['quote_allocations','quote_external_services','quote_stage_supplier_costs','quote_supplier_markups','quote_supplier_phase_splits','quote_site_trips','quote_billable_hourly_rates'];END IF;IF payments THEN selected:=selected||ARRAY['quote_payment_schedule_items'];END IF;
 FOREACH t IN ARRAY selected LOOP FOR r IN SELECT value FROM jsonb_array_elements(coalesce(s->'tables'->t,'[]')) LOOP maps:=maps||jsonb_build_object(r->>'id',gen_random_uuid());END LOOP;END LOOP;
 FOREACH t IN ARRAY selected LOOP EXECUTE format('DELETE FROM public.%I WHERE quote_id=$1',t) USING _quote_id;END LOOP;
 IF planning THEN DELETE FROM public.quote_stage_dependencies WHERE quote_id=_quote_id;DELETE FROM public.quote_stages WHERE quote_id=_quote_id;stages:=s->'tables'->'quote_stages';
 FOR r IN SELECT value FROM jsonb_array_elements(stages) LOOP r:=r-'parent_stage_id'-'linked_stage_id';IF NOT fee_values THEN r:=r||jsonb_build_object('budget',0,'retainer_monthly_amount',0);END IF;PERFORM public.quote_template_insert_rows('quote_stages',jsonb_build_array(r),maps,_quote_id);END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(stages) LOOP UPDATE public.quote_stages SET parent_stage_id=(maps->>(r->>'parent_stage_id'))::uuid,linked_stage_id=(maps->>(r->>'linked_stage_id'))::uuid WHERE id=(maps->>(r->>'id'))::uuid;END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(coalesce(s->'tables'->'quote_stage_dependencies','[]')) LOOP maps:=maps||jsonb_build_object(r->>'id',gen_random_uuid());END LOOP;PERFORM public.quote_template_insert_rows('quote_stage_dependencies',s->'tables'->'quote_stage_dependencies',maps,_quote_id);END IF;
 IF fees THEN settings:=s->'settings';IF NOT fee_values THEN settings:=settings||jsonb_build_object('valor',0,'construction_cost',NULL,'project_fee_calculation','{}'::jsonb);END IF;SELECT string_agg(format('%I=(jsonb_populate_record(NULL::public.fee_proposals,$1)).%I',key,key),',') INTO cols FROM jsonb_each(settings);IF cols IS NOT NULL THEN EXECUTE 'UPDATE public.fee_proposals SET '||cols||' WHERE id=$2' USING settings,_quote_id;END IF;END IF;
 FOREACH t IN ARRAY selected LOOP FOR r IN SELECT value FROM jsonb_array_elements(coalesce(s->'tables'->t,'[]')) LOOP IF NOT fee_values AND t<>'quote_payment_schedule_items' THEN FOREACH k IN ARRAY ARRAY['unit_cost','purchase_price','sale_price','sale_price_manual','amount','sale_rate','cost_rate_snapshot','sale_rate_snapshot','price_per_km','resource_hourly_rate'] LOOP IF r ? k THEN r:=r||jsonb_build_object(k,0);END IF;END LOOP;IF t='quote_site_trips' THEN r:=r||jsonb_build_object('resource_hourly_rates','{}'::jsonb);END IF;END IF;PERFORM public.quote_template_insert_rows(t,jsonb_build_array(r),maps,_quote_id);END LOOP;END LOOP;
 SELECT id INTO p FROM public.psa_proposals WHERE quote_id=_quote_id ORDER BY updated_at DESC,id LIMIT 1;IF(blocks OR layout) AND p IS NULL THEN INSERT INTO public.psa_proposals(quote_id,title,language,created_by) VALUES(_quote_id,q.titulo,coalesce(s->>'language','pt-PT'),auth.uid()) RETURNING id INTO p;END IF;
 IF blocks THEN DELETE FROM public.psa_proposal_blocks WHERE proposal_id=p;FOR r IN SELECT value FROM jsonb_array_elements(s->'blocks') LOOP maps:=maps||jsonb_build_object(r->>'id',gen_random_uuid());r:=r-'created_at'-'updated_at'||jsonb_build_object('proposal_id',p,'is_locked',false,'source_ref',coalesce(r->'source_ref','{}')||jsonb_build_object('quote_id',_quote_id));r:=jsonb_set(r,'{source_ref,quote_id}',to_jsonb(_quote_id::text));PERFORM public.quote_template_insert_rows('psa_proposal_blocks',jsonb_build_array(r),maps,_quote_id);END LOOP;END IF;
 IF layout THEN UPDATE public.psa_proposals SET style_settings=coalesce(s->'layout','{}') WHERE id=p;END IF;
 INSERT INTO public.quote_template_imports(quote_id,actor_id,template_id,before_state,after_hash) VALUES(_quote_id,auth.uid(),_template_id,b,md5(public.quote_template_capture(_quote_id)::text)) RETURNING id INTO import_id;RETURN import_id;
END $$;
CREATE OR REPLACE FUNCTION public.quote_undo_template_import(_import_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE operation public.quote_template_imports;q public.fee_proposals;state jsonb;t text;r jsonb;cols text;p uuid;
BEGIN
 IF NOT public.has_role(auth.uid(),'admin'::public.app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO operation FROM public.quote_template_imports WHERE id=_import_id FOR UPDATE;IF NOT FOUND OR operation.undone_at IS NOT NULL THEN RAISE EXCEPTION 'Import no longer undoable';END IF;
 SELECT * INTO q FROM public.fee_proposals WHERE id=operation.quote_id FOR UPDATE;IF q.is_locked OR q.pm_project_id IS NOT NULL OR q.locked_project_id IS NOT NULL OR q.quote_status<>'draft' THEN RAISE EXCEPTION 'Cannot undo a locked quote';END IF;
 IF md5(public.quote_template_capture(q.id)::text)<>operation.after_hash THEN RAISE EXCEPTION 'Quote changed after import; undo would overwrite later work';END IF;state:=operation.before_state;
 FOREACH t IN ARRAY ARRAY['quote_allocations','quote_external_services','quote_stage_supplier_costs','quote_supplier_markups','quote_supplier_phase_splits','quote_site_trips','quote_billable_hourly_rates','quote_payment_schedule_items','quote_stage_dependencies'] LOOP EXECUTE format('DELETE FROM public.%I WHERE quote_id=$1',t) USING q.id;END LOOP;
 DELETE FROM public.quote_stages WHERE quote_id=q.id;
 FOR r IN SELECT value FROM jsonb_array_elements(state->'tables'->'quote_stages') LOOP PERFORM public.quote_template_insert_rows('quote_stages',jsonb_build_array(r-'parent_stage_id'-'linked_stage_id'),'{}',q.id,true);END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(state->'tables'->'quote_stages') LOOP UPDATE public.quote_stages SET parent_stage_id=(r->>'parent_stage_id')::uuid,linked_stage_id=(r->>'linked_stage_id')::uuid,updated_at=(r->>'updated_at')::timestamptz WHERE id=(r->>'id')::uuid;END LOOP;
 FOREACH t IN ARRAY ARRAY['quote_stage_dependencies','quote_allocations','quote_external_services','quote_stage_supplier_costs','quote_supplier_markups','quote_supplier_phase_splits','quote_site_trips','quote_billable_hourly_rates','quote_payment_schedule_items'] LOOP PERFORM public.quote_template_insert_rows(t,state->'tables'->t,'{}',q.id,true);END LOOP;
 SELECT string_agg(format('%I=(jsonb_populate_record(NULL::public.fee_proposals,$1)).%I',key,key),',') INTO cols FROM jsonb_each(state->'quote') WHERE key<>ALL(ARRAY['id','updated_at']);EXECUTE 'UPDATE public.fee_proposals SET '||cols||' WHERE id=$2' USING state->'quote',q.id;
 SELECT id INTO p FROM public.psa_proposals WHERE quote_id=q.id ORDER BY updated_at DESC,id LIMIT 1;DELETE FROM public.psa_proposal_blocks WHERE proposal_id=p;
 IF state->'proposal'='null'::jsonb THEN DELETE FROM public.psa_proposals WHERE id=p;ELSE SELECT string_agg(format('%I=(jsonb_populate_record(NULL::public.psa_proposals,$1)).%I',key,key),',') INTO cols FROM jsonb_each(state->'proposal') WHERE key<>ALL(ARRAY['id','updated_at']);EXECUTE 'UPDATE public.psa_proposals SET '||cols||' WHERE id=$2' USING state->'proposal',p;PERFORM public.quote_template_insert_rows('psa_proposal_blocks',state->'blocks','{}',q.id,true);END IF;
 UPDATE public.quote_template_imports SET undone_at=now() WHERE id=_import_id;
END $$;
REVOKE ALL ON FUNCTION public.quote_template_preview(uuid,uuid),public.quote_import_full_template(uuid,uuid,jsonb,text),public.quote_undo_template_import(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.quote_template_preview(uuid,uuid),public.quote_import_full_template(uuid,uuid,jsonb,text),public.quote_undo_template_import(uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.quote_template_rewrite(jsonb,jsonb,boolean) FROM PUBLIC,anon,authenticated;